pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    let coupling = 1.0 + 2.0 * progress * progress;
    score += 40.0 * (1.0 - x) * (1.0 - x) * coupling;

    let dead = (1.0 - x).max(0.0);
    score += 25.0 * dead * dead * (1.0 - progress);

    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits post residual; stronger when exact or near-exact.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_left = post_residual - next_item_size;
        if nxt_left == 0 {
            score -= 60.0;
        } else {
            let fill = next_item_size as f64 / pr;
            score -= 24.0 * fill + 10.0 * (next_item_size as f64 / cap);
            if nxt_left <= 5 {
                score -= 14.0;
            } else if nxt_left <= 12 {
                score -= 5.0;
            }
        }
    } else if next_item_size > 0 && post_residual >= next_item_size * 3 / 4 {
        // near-miss: dead space almost usable by next item
        score += 4.0;
    }

    // Penalize leaving dead space more than twice the next item's size.
    if next_item_size > 0 && post_residual > next_item_size * 2 {
        score += 3.0;
    }

    score += 0.5 * open_bins_count as f64;

    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: open a fresh bin only for large items or late stream.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac >= 0.5 {
            score -= 13.0 * frac;
        } else {
            score += 24.0 * (1.0 - frac);
        }
        score -= 10.0 * (1.0 - progress);
        if mean_residual > 22.0 && open_bins_count > 3 {
            score += 14.0;
        }
        if progress > 0.75 && frac < 0.25 {
            score += 18.0;
        }
        if item_size >= bin_capacity * 9 / 10 {
            score -= 4.0;
        }
    } else {
        let used_frac = 1.0 - x;
        if used_frac > 0.8 {
            score -= 4.0;
        }
        if used_frac > 0.95 {
            score -= 3.0;
        }
        if post_residual > 20 && post_residual % 10 != 0 {
            score += (post_residual % 10) as f64 * 0.25;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        let nxt = next_item_size as f64;

        // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits after this placement: reward closeness to exact match.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            // Extra bonus for an exact match.
            if diff == 0.0 {
                score -= 60.0;
            }
        } else {
            // Next item will NOT fit: penalize proportionally to wasted potential.
            score += 30.0 + 20.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }

        // Coupling with mean residual: bins whose post-residual is far below the
        // mean residual are becoming outliers (dead space) -> penalize.
        let post_f = post_residual as f64;
        if mean_residual > 0.0 {
            let rel_gap = (post_f - mean_residual) / mean_residual;
            if rel_gap < 0.0 {
                score += 15.0 * (-rel_gap) * (0.5 + 0.5 * progress);
            } else {
                score -= 5.0 * rel_gap.min(2.0);
            }
        }
    } else {
        // Last item: just minimize post residual (handled by base score).
        score -= 10.0;
    }

    // Last-chance bin: only one bin can fit this item; strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer tighter bins in general: scale by how full the bin already is.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Early in the stream, keep bins balanced to preserve flexibility;
    // late in the stream, pack aggressively (favor low post_residual more).
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

