pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * (20.0 + 60.0 * progress);

    // Penalize dead space (small post_residual unusable by next item)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + progress);
    }

    // Reward perfect or near-perfect fills
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild penalty for opening new bins late in stream when others fit
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Prefer bins below mean residual (larger residuals first for big items)
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Penalize post-residuals in "awkward" harmonic bands (dead space that
    // typical items 1..100 rarely fill): bands (0.1,0.3), (0.4,0.5), (0.6,0.8).
    let band_penalty = if frac > 0.6 && frac < 0.8 {
        18.0
    } else if frac > 0.1 && frac < 0.3 {
        12.0
    } else if frac > 0.4 && frac < 0.5 {
        10.0
    } else {
        0.0
    };
    score += band_penalty;

    // Integer-division threshold: if post_residual cannot hold the next item,
    // this placement wastes the lookahead opportunity.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chaining: next item fits here afterwards.
            let chain = (next_item_size as f64) * (0.5 + 0.5 * (post_residual - next_item_size) as f64 / cap);
            score -= chain;
        } else {
            score += 8.0;
        }
    }

    // Perfect fit reward: modulo arithmetic on post_residual.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0; // round residual is more reusable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among several fitting bins, prefer tighter fits (smaller post_residual
        // already encoded) but add mild spread penalty.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual on empty bin = capacity - item_size).
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize mildly so it only wins when open bins are bad.
        score += 20.0;
        // But if item is large, a fresh bin is naturally good (large post_residual
        // is reusable), so reduce the penalty.
        score -= 0.1 * (item_size as f64);
        // Late in the stream, opening fresh bins is less useful.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    // Early stream: be greedy with tight fits; later, conserve bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap => nearly wasted capacity
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Non-linear dead-space penalty: gaps in [10, 25) can only host small items,
    // discount their usefulness quadratically.
    if post_residual >= 10 && post_residual < 25 {
        let gap = post_residual as f64;
        score += 0.5 * (25.0 - gap) * (25.0 - gap) / 25.0;
    }

    // Prefer bins whose residual was already "scarred" (low residual) to keep
    // large-capacity bins free for large items.
    score += 0.15 * (bin_residual as f64 - post_residual as f64);

    // Open-bin pressure: discourage proliferation of open bins unless the fit
    // is very tight.
    score += 2.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only allow opening a new bin if the item is
    // large and no tight fit exists; otherwise make the new bin unattractive.
    if bin_residual == bin_capacity {
        let tightness_available = (bin_residual - item_size) as f64;
        if fitting_bins_count > 0 && tightness_available < 20.0 {
            score += 500.0; // an open bin could take it tightly; don't open new
        } else {
            // New bin is fine for big items with no good alternative.
            score -= 10.0;
            if next_item_size > 0 && (next_item_size as f64) > tightness_available {
                score += 30.0; // next item won't fit this fresh bin's post state anyway
            }
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if next item nearly fits but not quite (creates trap).
    if next_item_size > post_residual && next_item_size - post_residual < 5 && post_residual > 0 {
        score += 15.0;
    }

    // Mean residual coupling: placing into a bin far below the mean residual
    // (i.e., consuming a large bin) is mildly penalized to balance load.
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Slight preference to fill older/nearly-full bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

