pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio subtracts from score.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Penalize small dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use leftover: mild penalty proportional to leftover
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * fill;
    }

    // New-bin candidate handling: opening a fresh bin is attractive early or when
    // the current bin would leave a very large unusable gap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bins less as stream progresses (consolidation phase),
        // but more when open bins are already fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 8.0 + 30.0 * progress - 0.1 * open_bins_count as f64;
        if fragmentation > 40.0 {
            score -= 10.0;
        }
        // Never open a new bin for a tiny item early on.
        if item_size < 30 && progress < 0.5 {
            score += 20.0;
        }
    } else {
        // Reward using bins whose residual is close to mean (balanced usage),
        // penalize extremes.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for emptier bins when many bins are open (reduce bin count).
    score -= 0.02 * open_bins_count as f64 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: residual cost grows super-linearly with stream progress
    let pr = post_residual as f64;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 12.0 * pr * prog2 + 8.0 * pr * pr * prog3;

    // Dead-space penalty: small post-residuals that are hard to fill later
    let dead = (1.0 - (pr / 20.0).min(1.0)) * (20.0 - pr).max(0.0);
    score += dead * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 - progress);
    }

    // Tight fit reward, scaled by progress
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 10.0 * (1.0 - (next_item_size as f64 / post_residual as f64).min(1.0));
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate: penalize early, relax late; prefer opening when mean residual is fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 * (1.0 - progress) - 15.0 * progress * fragmentation / (bin_capacity as f64);
        score += open_bins_count as f64 * 0.5;
    }

    // Mild preference for fuller bins relative to mean residual
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are near-sealed; reward sealing bins tightly.
    let pr = post_residual;
    let class = pr / 10; // integer division: coarse residue class 0..=9
    match class {
        0 => score -= 8.0,                 // almost full: excellent seal
        1 => score -= 5.0,                 // good seal
        2 => score -= 2.5,
        3 => score -= 1.0,
        5 => score += 2.0,                 // half-empty: mediocre
        7 => score += 3.5,
        8 => score += 4.5,
        9 => score += 6.0,                 // nearly untouched bin
        _ => {}
    }

    // Fine modulo bonus: leftover divisible by small harmonics pairs well
    // with typical item granularities (sizes 1..100 often cluster mod 5/10).
    if pr % 10 == 0 && pr > 0 {
        score -= 1.5;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 0.75;
    }

    // Lookahead coupling: if the next item exactly fills the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            // next item still fits: mild reward scaled by how much slack remains
            let slack = (pr - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's residue: penalize residue that
            // is "just barely" too small (worst dead space zone).
            let overshoot = (next_item_size - pr) as f64;
            if overshoot <= 20.0 {
                score += overshoot * 0.4;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill = item_size as f64 / cap;
        // penalize new bins generally, less so for big items / late stream
        score += 10.0 - 6.0 * fill - 2.0 * progress;
        // if many bins already open and mean residual is low, prefer new bin
        if mean_residual < fill * cap * 0.5 {
            score -= 3.0;
        }
        if open_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // prefer filling bins with residual close to item size (tight fit)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 3.0 * tightness * tightness;
    }

    // Prefer bins below mean residual (consolidate emptier space first is
    // bad; instead target bins with residual near item to keep big holes).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.02 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable, penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (post_residual == 0).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual matches the next item (chain fitting).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, allow opening a new bin for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 1.5;

    // New-bin candidate: penalize mildly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.05;
        // But if item is large and mean residual is small, new bin is attractive.
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Slight preference for bins tighter than average (better packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item fits exactly into remaining space after a second placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step_waste = post_residual - next_item_size;
        // Reward small two-step waste (near-perfect chain fit)
        score -= 2.0 * (bin_capacity as f64 - two_step_waste as f64) * 0.5;
        // Extra bonus if the chain leaves (almost) nothing behind
        if two_step_waste <= 5 {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // Next item would NOT fit here: penalize proportionally to how far off
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 1.5;
    }

    // Penalize dead space: small post_residual that likely can't fit anything (min item 1..10)
    if post_residual < 10 {
        score -= 50.0; // actually good: bin nearly full, reward it
    } else {
        // Larger residual relative to capacity is worse unless next item uses it
        score += (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // Compare against mean residual: bins tighter than mean are better targets
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, more so late in stream or when a last-chance bin exists
        score += 40.0;
        if fitting_bins_count == 1 {
            score += 100.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 10.0;
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, reward tight fits more.
    let coupling = 1.0 + 2.0 * progress * progress;
    score += 40.0 * (1.0 - x) * (1.0 - x) * coupling;

    // Penalize large dead space quadratically, weighted by remaining stream length.
    let dead = (1.0 - x).max(0.0);
    score += 25.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item could also fit into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    }

    // Slight penalty proportional to number of open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins near the mean residual (smooth term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue
    // classes modulo small integers, rewarding leftovers that stay "usable"
    // for typical future items (multiples of 10) and penalizing dead space.
    let pr = post_residual;
    let class10 = pr % 10;
    if class10 != 0 {
        // leftover not aligned to the 10-grid: penalize proportionally to raggedness
        score += (10 - class10) as f64 * 0.8;
    }

    // Integer-division thresholds on post_residual: leftover buckets
    // 0 = perfect fill, 1..=20 tight, 21..=50 medium, >50 wasteful
    if pr == 0 {
        score -= 60.0; // perfect closure is excellent
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 50 {
        score += 5.0;
    } else {
        score += 15.0; // big hole left behind
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (harmonic chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // partial fit quality: how much of the leftover the next item consumes
            let fill = next_item_size as f64 / pr as f64;
            score -= 20.0 * fill;
            // raggedness of the chain leftover
            let nxt_left = pr - next_item_size;
            if nxt_left % 10 != 0 {
                score += (nxt_left % 10) as f64 * 0.5;
            }
        } else {
            // next item cannot use this leftover: mild penalty if leftover is small
            if pr < next_item_size {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when the item is large relative to capacity (good anchor)
    // and no strong fit exists elsewhere.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac >= 0.5 {
            score -= 10.0 * frac; // large items anchor fresh bins well
        } else {
            score += 20.0 * (1.0 - frac); // small items waste a fresh bin
        }
        // prefer new bins early in the stream when few bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Contextual pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        let gap = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * gap;
        score -= 1.5 * open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    }

    // Prefer tight fits overall: reward small post_residual relative to capacity.
    score -= 0.1 * (bin_capacity - pr) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: unusable gaps (too small for smallest plausible item)
    // are heavily penalized. Anything below ~10 units is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly (waste-free packing).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when the item fits reasonably well.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only allow opening a fresh bin when current
    // bins would create severe dead space, or when lookahead fits better there.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + open_bins_count as f64 * 0.5;
        // If the next item would be stranded by this placement, opening a new
        // bin may be justified: discount the new bin slightly.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score -= 12.0;
        }
        // Late in the stream, opening new bins is less costly relative to
        // leftover sprawl; slight discount.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "cramped" bin; placing here consolidates waste — reward slightly.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 && residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    }

    // Lookahead synergy: if the post residual exactly accommodates the next item,
    // reward this placement (chains two items into one bin efficiently).
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already rewarded).

    // Aggressive 2-step lookahead: strongly reward when the NEXT item fits exactly
    // into the post-residual (perfect chain match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            // Reward proportional to how well the next item consumes leftover space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize dead space relative to next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than the mean residual is good (tight packing).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable fragments (< smallest plausible item = 1,
    // but fragments below 10 are hard to use in practice).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if open bins leave bad fits.
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual relative to item size).
    if post_residual > 0 {
        score -= (item_size as f64 / post_residual as f64) * 8.0;
    } else {
        score -= 30.0; // perfect fit
    }

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward when next item exactly chains
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // wasted space blocking next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins overall (relative to mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Time horizon: early in stream, be more willing to open new bins;
    // late in stream, prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Many open bins: encourage consolidation.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Reduce penalty if no good alternative exists.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if post_residual > 0 && (bin_capacity - post_residual) as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0; // item is large, fine to start fresh bin
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 5.0; // fresh bin can chain next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post_residual) mildly.
    // Late stream: penalize residual more strongly to consolidate.
    let poly = 1.0 + 2.0 * progress * progress + 3.0 * progress.powi(3);
    score += poly * norm_pr * norm_pr * cap * 0.5;

    // Reward filling bins completely (post_residual near zero), smoothly.
    score -= (1.0 - norm_pr).powi(4) * cap * 0.3;

    // Interaction: small post-residual relative to next item wastes space.
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let waste = (pr - nx).max(0.0) / cap;
        score += waste * waste * cap * (0.2 + 0.8 * progress);
        // Bonus if next item fits exactly in post_residual.
        let fits_next = if nx <= pr { 1.0 } else { 0.0 };
        score -= fits_next * 5.0 * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_item) * (1.0 + progress);
    }

    // Slight preference toward using bins with larger residuals relative to mean.
    let mr = mean_residual / cap;
    score -= (norm_pr - mr) * 3.0 * (0.5 + progress);

    // Mild penalty on opening new bins when many bins are open and stream is early.
    if bin_residual == bin_capacity {
        score += 2.0 + 8.0 * (1.0 - progress) * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual (capacity fractions / integer division thresholds)
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / 10).min(9); // coarse harmonic class of leftover
    // Small leftovers are dead space: penalize classes 1..3 (1-30 residual) lightly, big leftovers fine
    score += match class {
        0 => -200.0,                    // 0 residual handled above, tiny leftover great
        1 => 15.0,                      // 10-19: awkward sliver
        2 => 25.0,                      // 20-29: moderately awkward
        3 => 10.0,                      // 30-39: still placeable for min items
        _ => -5.0,                      // >=40: flexible residual
    };

    // Modulo-10 coupling: leftover that is a multiple of 10 pairs well with typical sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    // Odd leftover penalized slightly
    if post_residual % 2 == 1 {
        score += 5.0;
    }

    // Lookahead: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;             // chain perfect fit
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 30.0 * (rem2 as f64 / c);
            if rem2 % 10 == 0 { score -= 10.0; }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 0.05 * pr;
        }
        // harmonic class match: leftover divisible by next item size
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer tighter existing bins (best-fit refinement) scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (bin_residual as f64 - mean_residual) * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): make it attractive only when leftovers are bad
    if bin_residual == bin_capacity {
        score = 60.0 + 0.3 * mean_residual - 40.0 * progress;
        if fitting_bins_count == 0 { score -= 100.0; }
        if next_item_size > 0 && next_item_size >= 60 { score -= 20.0; }
    }

    // Mild penalty for bin sprawl when many bins already open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap that cannot hold even the minimum item (1..100 unknown dist,
    // use a conservative small-gap threshold scaled to next item) is toxic.
    if post_residual > 0 {
        // Dead space: gap too small for the next item (or absolutely tiny)
        let min_useful = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < min_useful {
            // The smaller and more useless the gap, the worse
            score += (min_useful - post_residual) as f64 * 6.0;
            // Extra penalty if the gap is below any plausible item size
            if post_residual < 10 {
                score += 40.0;
            }
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling
    // existing bins over opening new ones — unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large and gap left is small
        let leftover = (bin_capacity - item_size) as f64;
        score = leftover * 1.2 + open_pressure * 2.0;
        // If existing bins are fragmented (high mean residual), a fresh bin is fine
        score -= mean_residual * 0.15;
    } else {
        score -= open_pressure * 0.5;
        // Prefer bins whose residual is below average (consolidating small gaps)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space relative to mean residual across open bins.
    let residual_f = post_residual as f64;
    if residual_f > mean_residual {
        score += 0.5 * (residual_f - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - residual_f);
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= residual_f {
            // Next item fits perfectly into this bin's leftover -> strong reward.
            let diff = (residual_f - next).abs();
            score -= 8.0 * (1.0 - diff / bin_capacity as f64);
            // Bonus for exact match.
            if diff == 0.0 {
                score -= 12.0;
            }
            // If next item also fits the current bin together with this one, slight penalty
            // for wasting the pairing opportunity elsewhere.
            if item_size as f64 + next <= bin_residual as f64 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use the leftover: penalize proportional dead space.
            score += 0.3 * next * (residual_f / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - residual_f / bin_capacity as f64);

    // New empty bin: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (bin_residual as f64);

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual < 25 {
        score += 4.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // Penalize if this bin is the only fitting option and next item would suffer.
        if fitting_bins_count == 1 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: discourage opening new bins unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else if fitting_bins_count == 1 {
            score += 10.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Global state coupling: prefer bins whose residual is close to the mean residual
    // (keeps residuals uniform, leaving large bins for large items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mildly prefer bins with more residual when many bins are open (balance load).
    score -= 0.02 * (bin_residual as f64) * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress) - pr_norm * progress * 0.5;

    // Reward tight fits, more so as stream progresses
    let tight_bonus = -2.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + progress);

    // Penalize dead space relative to mean residual
    let dead = if pr > 0.0 { (pr - mean_residual).abs() / cap } else { 0.0 };
    let dead_pen = 1.5 * dead * dead;

    // Lookahead coupling: reward leaving space for next item
    let nx = next_item_size as f64 / cap;
    let look = if next_item_size > 0 {
        -1.0 * (1.0 - (pr_norm - nx).abs()) * (1.0 - (pr_norm - nx).abs())
    } else { 0.0 };

    // Last-chance bin bonus
    let last = if fitting_bins_count == 1 { -1.2 } else { 0.0 };

    let mut score = pr + 10.0 * poly + tight_bonus + dead_pen + 8.0 * look + last;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a convex penalty
    // so that moderate slack is punished more than linear.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    score += 0.6 * (pr / cap) * (pr / cap) * cap;

    // Harmonic class logic: classify post_residual into residue classes.
    // Items of size 10..80 with capacity 100 create "harmonic" residual
    // buckets: 0 (perfect), small primes (1..5), mid (6..19), large (20+).
    if post_residual == 0 {
        score -= 30.0; // perfect closure: bin exactly filled
    } else if post_residual <= 5 {
        score -= 12.0; // near-perfect: dead space negligible
    } else if post_residual <= 19 {
        // mid-class: value depends on whether the NEXT item can use it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0; // lookahead item fits: excellent chaining
        } else {
            score += 6.0; // stranded mid-slack
        }
    } else {
        // large residual: good if next item exploits it, bad otherwise
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 4.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are reusable "harmonics".
    let harmonics: [u32; 6] = [10, 20, 25, 30, 40, 50];
    for h in harmonics.iter() {
        if post_residual >= *h && post_residual % *h == 0 {
            score -= 4.0;
            break;
        }
    }

    // Integer-division thresholds: post_residual / item_size quotient.
    // If the residual could hold >= 2 more copies of this item class,
    // the bin is efficiently used.
    if item_size > 0 && post_residual / item_size >= 2 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize the empty bin mildly so
    // open bins with reasonable fit win, but relax the penalty when the
    // current item is large relative to residual capacity elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 10.0;
        // If item nearly fills a bin by itself, opening a fresh bin is fine.
        if item_size as f64 >= 0.7 * cap {
            new_bin_penalty -= 6.0;
        }
        // Late in the stream, avoid proliferating bins unnecessarily.
        new_bin_penalty += 4.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, prefer reuse.
        if open_bins_count > 2 && mean_residual > (item_size as f64) {
            new_bin_penalty += 3.0;
        }
        // If this is the only fitting option, opening new bin is neutral.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead coupling: penalize placements that leave residual just
    // barely too small for the next item (wasted potential).
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 5.0;
    }

    // Mild preference for consolidating into fewer bins early on.
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 1.0;
    }

    score
}

