    } else if pr < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if pr == 0 {
        score -= 40.0;
    }

    // Chain fitting with graded reward for exact / fractional / leftover reuse.
    if next_item_size > 0 {
        if next_item_size == pr {
