        }
        if open_bins_count > 6 && mean_residual > item_size as f64 * 1.2 {
            score += 9.0;
        }
        if item_size >= bin_capacity * 9 / 10 {
            score -= 4.0;
        }
    } else {
        // Prefer bins that will be well filled after placement.
        let used_frac = 1.0 - (pr as f64 / bin_capacity as f64);
        if used_frac > 0.8 {
            score -= 4.0;
        }
        if used_frac > 0.95 {
            score -= 3.0;
        }
        // Penalize residuals whose last digit creates unusable slivers.
        if pr > 20 && pr % 10 != 0 {
            score += (pr % 10) as f64 * 0.25;
        }
        // Reward round-number residuals that are still useful.
        if pr > 0 && pr % 5 == 0 && pr <= 30 {
            score -= 2.0;
        }
        // Tighter-than-average bins pack better.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

