pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Dead-space avoidance: tiny gaps are unusable.
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Chain fitting: residual matches next item exactly -> strong reward.
    if next_item_size > 0 && pr >= next_item_size {
        if pr == next_item_size {
            score -= 50.0;
        } else {
            let fill = next_item_size as f64 / pr as f64;
            score -= 20.0 * fill;
            let nxt_left = pr - next_item_size;
            if nxt_left <= 3 {
                score -= 8.0;
            } else if nxt_left <= 12 {
                score -= 3.0;
            }
            if nxt_left % 10 != 0 {
                score += (nxt_left % 10) as f64 * 0.7;
            }
            // Two-item lookahead: after next item, residual fits current item size.
            if nxt_left >= item_size && nxt_left - item_size <= 6 {
                score -= 5.0;
            }
        }
    }
    // Gap that fits neither next item nor is useful.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 6.0;
        // Odd sliver nobody can use.
        if pr < item_size {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count <= 2 && pr >= item_size {
