    } else if fitting_bins_count >= 5 && pr >= item_size {
        score += 2.0;
    }

    // Open-bin pressure grows with progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 1.5;

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac >= 0.5 {
            score -= 13.0 * frac;
        } else {
            score += 24.0 * (1.0 - frac);
        }
        score -= 10.0 * (1.0 - progress);
