        }
        if progress > 0.75 && frac < 0.25 {
            score += 18.0;
        }
        // Fresh-bin residual exactly matching next item -> open it.
        if next_item_size > 0 && item_size < bin_capacity {
            let fresh_res = bin_capacity - item_size;
            if fresh_res == next_item_size {
                score -= 20.0;
            } else if fresh_res > next_item_size && fresh_res % next_item_size == 0 {
                score -= 6.0;
            }
        }
        if item_size >= bin_capacity * 9 / 10 {
            score -= 4.0;
        }
    } else {
        let used_frac = 1.0 - (pr as f64 / bin_capacity as f64);
        if used_frac > 0.8 {
            score -= 4.0;
        }
        if used_frac > 0.95 {
            score -= 3.0;
        }
        // Prefer residuals that current item divides cleanly.
        if pr > 0 && pr % item_size == 0 && pr / item_size <= 3 {
            score -= 3.0;
        }
    }

    // Slight preference for bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

