        if progress > 0.75 && frac < 0.3 { score += 20.0; }
        // Fresh-bin residual exactly matches next item -> strong chain bonus
        if next_item_size > 0 && bin_capacity - item_size == next_item_size { score -= 22.0; }
        if next_item_size > 0 && bin_capacity - item_size > next_item_size
            && (bin_capacity - item_size) % next_item_size == 0 { score -= 6.0; }
        // Self-chaining: residual divisible by current item
