        if post_residual == 0 { score -= 40.0; }
        return score;
    }

    // ---- Existing bins ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post_f = pr as f64;
        if post_f >= nxt {
            let diff = post_f - nxt;
            if diff == 0.0 {
                score -= 60.0;
            } else {
                score -= 26.0 * (nxt / post_f);
                if diff <= 3.0 { score -= 8.0; }
                if diff <= 12.0 { score -= 3.0; }
                // dead-space ratio after placing next item
                let dead = diff / cap;
                if dead < 0.05 { score -= 2.0; }
                else if dead > 0.15 { score += 5.0 * dead; }
                // two-step lookahead: residual after next fits current item size
                if diff >= item_size as f64 && diff - item_size as f64 <= 6.0 { score -= 5.0; }
                // residual cleanly divisible by next item (predictable future fills)
                if nxt > 0.0 && diff % nxt == 0.0 && diff / nxt <= 3.0 { score -= 4.0; }
            }
        } else {
            // next item won't fit here: penalize proportional to overflow
            score += 12.0 + 22.0 * (nxt - post_f) / cap;
        }

