        if item_size > 0 && waste % item_size == 0 { score -= 3.0; }
    }

    // last-chance bin: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count <= 2 {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // fill-ratio preference
