pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;

        if post_residual >= next_item_size {
            let nxt_left = post_residual - next_item_size;
            let diff = (pr - nxt).abs();
            // Reward closeness to exact two-step match
            score -= 40.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            // Reward small chainable leftovers
            if nxt_left <= 3 {
                score -= 8.0;
            } else if nxt_left <= 12 {
                score -= 3.0;
            }
            if nxt_left % 5 == 0 && nxt_left <= 25 {
                score -= 2.5;
            }
            // Penalize unusable slivers left after next placement
            if nxt_left > 0 && nxt_left < item_size.min(next_item_size) as f64 {
                score += 4.0;
            }
            // Dead-space band penalty grows late in the stream
            let dead = nxt_left / cap;
            if dead >= 0.08 && dead <= 0.25 {
                score += (3.0 + 6.0 * progress) * dead;
            }
            // Chainable: leftover divisible by next item (multi-placement lookahead)
            if next_item_size > 0 && nxt_left % next_item_size == 0 && nxt_left / next_item_size as u32 <= 3 {
                score -= 3.0;
            }
            // Combined waste small => near-perfect pair
            if nxt_left <= 5 {
                score -= 12.0;
            }
        } else {
            // Next item will NOT fit: penalize wasted potential
            score += 30.0 + 20.0 * (nxt - pr) / cap;
            // Sliver residual: nearly unusable, extra penalty
            if pr < nxt && pr < item_size as f64 {
                score += 6.0;
            }
        }

        // Mean-residual coupling: penalize bins drifting below mean (dead space outliers)
        if mean_residual > 0.0 {
            let rel_gap = (pr - mean_residual) / mean_residual;
            if rel_gap < 0.0 {
                score += 15.0 * (-rel_gap) * (0.5 + 0.5 * progress);
            } else {
                score -= 5.0 * rel_gap.min(2.0);
            }
        }
    } else {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        // Many competitors: reward tight fills only
        let tight = 1.0 - (item_size as f64 / pr.max(1.0));
        score += tight * 2.0;
    }

    // Prefer tighter bins
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= 10.0 * fill_ratio;

    // Aggressive late packing
    score -= 20.0 * progress * (1.0 - pr / cap);

    // NEW-BIN candidate logic (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac >= 0.5 {
            score -= 13.0 * frac;
        } else {
            score += 24.0 * (1.0 - frac);
        }
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: avoid opening more bins
        if mean_residual > 22.0 && open_bins_count > 3 {
            score += 14.0;
        }
        if progress > 0.75 && frac < 0.25 {
            score += 18.0;
        }
        if open_bins_count > 6 && mean_residual > item_size as f64 * 1.2 {
            score += 9.0;
        }
        // Perfect complement: fresh bin leftover exactly matches next item
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) > next_item_size
            && (bin_capacity - item_size) % next_item_size == 0 {
            score -= 6.0;
        }
