pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;
    let mut score = pr as f64;

    let coupling = 1.0 + 2.0 * progress * progress;
    score += 40.0 * (1.0 - x) * (1.0 - x) * coupling;

    let dead = (1.0 - x).max(0.0);
    score += 25.0 * dead * dead * (1.0 - progress);

    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else if fitting_bins_count >= 5 && post_residual >= item_size {
        score += 2.0;
    }

    // Lookahead: reward if next item fits post residual; stronger when exact or near-exact.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_left = post_residual - next_item_size;
        if nxt_left == 0 {
            score -= 60.0;
        } else {
            let fill = next_item_size as f64 / pr;
            score -= 24.0 * fill + 10.0 * (next_item_size as f64 / cap);
            if nxt_left <= 5 {
                score -= 14.0;
            } else if nxt_left <= 12 {
                score -= 5.0;
            }
            // divisibility of leftover by next item: chainable residual
            if next_item_size > 0 && nxt_left % next_item_size == 0 {
                score -= (nxt_left / next_item_size) as f64 * 1.2;
            }
            // dead-space ratio after placing next item
            let dead2 = nxt_left as f64 / cap;
            if dead2 < 0.05 {
                score -= 2.0;
            } else if dead2 > 0.15 {
                score += 4.0 * dead2;
            }
            // two-item lookahead: residual fits item after next
            if nxt_left >= item_size && nxt_left.saturating_sub(item_size) <= 6 {
                score -= 5.0;
            }
        }
    } else if next_item_size > 0 && post_residual >= next_item_size * 3 / 4 {
        score += 4.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    if next_item_size > 0 && post_residual > next_item_size * 2 {
        score += 3.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < item_size {
        score -= 2.5;
    }
    if post_residual == item_size {
        score -= 5.0;
    }
    if post_residual == 0 {
        score -= 40.0;
    }

    score += 0.5 * open_bins_count as f64;

    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac >= 0.5 {
            score -= 13.0 * frac;
        } else {
            score += 24.0 * (1.0 - frac);
        }
        score -= 10.0 * (1.0 - progress);
        if mean_residual > 22.0 && open_bins_count > 3 {
            score += 14.0;
        }
        if progress > 0.75 && frac < 0.25 {
            score += 18.0;
        }
        if item_size >= bin_capacity * 9 / 10 {
            score -= 4.0;
        }
        // perfect pairing: fresh bin residual equals next item exactly
        if next_item_size > 0 && item_size < bin_capacity && (bin_capacity - item_size) == next_item_size {
            score -= 20.0;
        }
        if next_item_size > 0 && item_size < bin_capacity && (bin_capacity - item_size) > next_item_size && (bin_capacity - item_size) % next_item_size == 0 {
            score -= 6.0;
        }
        if item_size > 0 && item_size < bin_capacity && (bin_capacity - item_size) % item_size == 0 && (bin_capacity - item_size) / item_size <= 4 {
            score -= 7.0;
        }
        if frac > 0.6 && open_bins_count > 2 && mean_residual / cap < 0.35 {
