    let mut score = post_residual as f64 ;
    let score = score * 0.95 + (bin_capacity as f64) * 0.05 ;
    if post_residual > 0 && post_residual < 10 { score += 60.0 ; }
    else if post_residual < 20 { score += 12.0 ; }
    if post_residual == 0 { score -= 40.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { score += 6.0 ; }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 25.0 ; }
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress) ;
    score += pressure * 1.5 ;
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.05 ;
        if item_size > 60 && mean_residual < item_size as f64 { score -= 30.0 ; }
        // refined new-bin logic: scale by item fraction and progress
        let frac = item_size as f64 / bin_capacity . max (1) as f64 ;
        if frac >= 0.5 { score -= 13.0 * frac ; }
        score -= 10.0 * (1.0 - progress) ;
        if mean_residual > 22.0 && open_bins_count > 3 { score += 14.0 ; }
        if open_bins_count > 6 && mean_residual > item_size as f64 * 1.2 { score += 9.0 ; }
