pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but with a twist:
    // dead space that is too small to ever hold the next item is worthless.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can chain the next item, scaled by how snugly
            // the next item would fit into the post residual.
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.25 * chain_fit.min(40.0);
        } else {
            // Penalize creating dead space below the next item's size,
            // especially when it is "useless small" (hard for future items too).
            let dead = post_residual as f64;
            score += 6.0 + 0.35 * dead;
        }

        // Exact chain match: post_residual == next_item_size is perfect.
        if post_residual == next_item_size {
            score -= 14.0;
        }
    } else {
        // No lookahead: just prefer tightest fit.
        score -= 4.0;
    }

