        score -= 0.15 * (mean_residual - residual_f);
    } else {
        score += 0.10 * (residual_f - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin gets a mild handicap so we
    // only open new bins when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if the current item is large relative to capacity and no good
        // chain exists, the empty bin becomes more attractive is handled by
        // the natural ordering; add slight progress-based relaxation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress;
    }

    // Prefer keeping the number of open bins from exploding: when many bins
    // are open, filling any existing bin is slightly favored.
    score += 0.05 * open_bins_count as f64;

    score
}

