    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 20.0;
        // If many bins fit the item, opening a new one is almost always bad.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // Early in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If mean residual is large, open bins have plenty of room; don't open new.
        if mean_residual > item_size as f64 * 2.0 {
            score += 20.0;
        }
    }

    // Mild preference for fuller bins among open bins (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight bonus for using bins when many are open (balance load).
    if open_bins_count > 5 {
        score -= 2.0;
    }

    // Time-horizon coupling: late in the stream, tighten packing aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

