            if nxt_left > 0 && nxt_left < next_item_size && nxt_left < item_size {
                score += 3.0;
            }
            if item_size > 0 && nxt_left % item_size == 0 && nxt_left / item_size <= 3 {
                score -= 2.8;
            }
            if next_item_size > 0 && item_size > 0
                && nxt_left >= next_item_size + item_size
