                && nxt_left - next_item_size - item_size <= 3 {
                score -= 4.0;
            }
            let dead2 = nxt_left as f64 / cap;
            if dead2 < 0.05 {
                score -= 2.5;
            } else if dead2 > 0.15 {
                score += 4.5 * dead2;
            }
            if nxt_left % 10 != 0 {
                score += (nxt_left % 10) as f64 * 0.5;
            }
            if nxt_left % 5 == 0 && nxt_left <= 25 {
                score -= 2.8;
            }
            if nxt_left > 0 && nxt_left < 8 && fitting_bins_count <= 2 {
                score -= 3.0 * (1.0 - progress);
            }
            if dead2 > 0.10 && dead2 < 0.18 && nxt_left < next_item_size {
                score += 2.0 * dead2 * 10.0;
            }
            // Extra band: mid dead-space with alternatives — prefer tighter bins.
            if dead2 >= 0.18 && dead2 <= 0.30 && fitting_bins_count > 1 {
                score += 3.5 * dead2 * (0.5 + progress);
            }
            // Perfect two-item landing (next + item fills residual exactly).
            if nxt_left == item_size {
                score -= 6.0;
            }
            // Chain landing: residual divisible by next item for a few repeats.
            if nxt_left > 0 && nxt_left < 100 {
                let chain = nxt_left / next_item_size;
                let chain_rem = nxt_left % next_item_size;
                if chain_rem == 0 && chain >= 1 && chain <= 5 {
                    score -= 1.8 * chain as f64 * (1.0 - progress);
                }
                if chain_rem > 0 && chain_rem <= 3 && chain >= 1 {
                    score -= 1.2;
                }
            }
            // Residual left below ~half mean residual — good compaction.
            if nxt_left > 0 && (nxt_left as f64) <= mean_residual * 0.55 {
                score -= 1.6 * (1.0 - progress);
            }
        }
    } else if next_item_size > 0 && post_residual >= next_item_size * 3 / 4 {
        score += 6.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    if next_item_size > 0 && post_residual > next_item_size * 2 {
        score += 3.0;
    }

    score += 0.5 * open_bins_count as f64;

    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac >= 0.5 {
            score -= 13.5 * frac;
        } else {
            score += 24.0 * (1.0 - frac);
        }
        score -= 10.0 * (1.0 - progress);
        if mean_residual > 22.0 && open_bins_count > 3 {
            score += 14.0;
        }
        if progress > 0.75 && frac < 0.25 {
            score += 18.0;
        }
        if item_size >= bin_capacity * 9 / 10 {
            score -= 4.0;
        }
        if next_item_size > 0 && item_size < bin_capacity {
            let left = bin_capacity - item_size;
            if left == next_item_size {
                score -= 20.0;
            } else if left > next_item_size && left % next_item_size == 0 {
                score -= 6.0;
            }
            if next_item_size + item_size > bin_capacity {
                score += 3.0;
            }
            // Exact two-item fill of a fresh bin.
            if item_size + next_item_size == bin_capacity {
                score -= 9.0;
            }
        }
        if item_size > 0 && item_size < bin_capacity {
            let left = bin_capacity - item_size;
            if left % item_size == 0 && left / item_size <= 4 {
                score -= 7.0;
            }
        }
        let left = (bin_capacity - item_size) as f64;
        if left >= mean_residual * 0.9 && left <= mean_residual * 1.1 {
            score -= 3.5;
        }
        if fitting_bins_count <= 2 && open_bins_count > 2 && frac >= 0.35 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.6 && frac < 0.6 && open_bins_count > 1 {
            score += 4.0 * (progress - 0.6) * 10.0;
            if open_bins_count > 6 {
                score += 2.0 * (progress - 0.6) * 10.0;
            }
        }
        if frac >= 0.85 {
            score -= 5.5;
        }
        if progress < 0.25 && frac >= 0.45 && open_bins_count < 4 {
            score -= 3.2;
        }
        // Big item into fresh bin when open bins are already loose.
        if frac > 0.6 && open_bins_count > 2 && mr_ratio < 0.35 {
            score -= 6.5 * frac;
        }
        // Complement in the [next, 2*next) band — perfect landing zone.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) < next_item_size * 2 && frac >= 0.3 {
            score -= 2.5;
        }
        // Mid-stream large item with tight open bins — prefer fresh bin.
        if progress > 0.35 && progress < 0.75 && frac < 0.4 && mr_ratio > 0.5 {
            score += 3.0;
        }
        // Loose bins and decently large item: fresh bin helps consolidation.
        if mr_ratio > 0.30 && frac >= 0.4 && open_bins_count > 4 {
            score -= 4.0 * frac * (1.0 - progress);
        }
    } else {
        let used_frac = 1.0 - x;
        if used_frac > 0.8 {
            score -= 4.0;
        }
        if used_frac > 0.95 {
            score -= 3.0;
        }
        if post_residual > 20 && post_residual % 10 != 0 {
            score += (post_residual % 10) as f64 * 0.25;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 2.2;
        }
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
            score -= 3.2;
        }
        if post_residual == item_size {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < item_size {
            score -= 2.5;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < next_item_size {
            score += 3.0;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let sliver = post_residual - next_item_size;
            if sliver >= 1 && sliver <= 3 && sliver < item_size {
                score += 2.5;
            }
        }
        let dead_ratio = pr / cap;
        if dead_ratio > 0.3 && used_frac > 0.5 {
            score += 2.0 * dead_ratio * dead_ratio * 10.0;
        }
        if dead_ratio > 0.2 && open_bins_count > 6 {
            score += 1.8 * dead_ratio;
        }
        if dead_ratio > 0.12 && dead_ratio < 0.3 && used_frac > 0.7 {
            score += 1.2 * dead_ratio * (1.0 - progress);
        }
        if dead_ratio > 0.05 && dead_ratio <= 0.12 && next_item_size > 0 && post_residual < next_item_size {
            score += 1.5 * (1.0 - progress);
        }
        if dead_ratio > 0.22 && dead_ratio < 0.28 && used_frac > 0.85 {
            score += 2.5 * dead_ratio;
        }
        if post_residual > 0 {
            let d3 = pr / cap;
            if d3 >= 0.08 && d3 <= 0.22 {
                score += (3.0 + 5.0 * progress) * d3;
            }
        }
        if fitting_bins_count > 4 {
            let tight = 1.0 - (item_size as f64 / pr.max(1.0));
            score += tight * 1.5;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 4.0;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let rem = post_residual - next_item_size;
            if rem >= next_item_size && rem % next_item_size == 0 {
                score -= 2.4;
            }
            if rem > 0 && rem < next_item_size / 3 {
                score += 1.6;
            }
        }
        if used_frac > 0.7 && next_item_size > 0 && pr < mean_residual * 0.6 {
            score -= 1.5;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual + next_item_size) % 10 == 0 {
            score -= 1.8;
        }
        // Near-exact fill with small residual and next fits — strong bonus.
        if used_frac > 0.6 && post_residual > 0 && post_residual <= 10
            && next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        // Penalize residual far above mean when bin is loose.
        if mr_ratio > 0.45 && used_frac < 0.6 {
            score += 1.5;
        }
        // Leaving residual above 1.5x mean with many bins — mild penalty.
        if post_residual > item_size && (post_residual - item_size) as f64 > mean_residual * 1.5 && open_bins_count > 3 {
            score += 2.0;
        }
        // Waste-after-next landing: penalize slivers smaller than both items.
        if next_item_size > 0 && post_residual >= next_item_size {
            let waste_after = (post_residual - next_item_size) as f64;
            if waste_after > 0.0 && waste_after < (item_size as f64).min(next_item_size as f64) {
                score += 1.4 * (1.0 - waste_after / 5.0);
            }
        }
    }

    if post_residual == 0 {
        score -= 40.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills mildly; late in the stream, tighten aggressively.
    let norm_post = post / cap;
    let coupling = norm_post * norm_post * (1.0 + 3.0 * progress) + norm_post * (0.5 + 1.5 * progress);
    score += 12.0 * coupling;

    // Reward near-perfect fits (post_residual close to zero) with a smooth bonus.
    let perfect = (1.0 - norm_post).powi(6);
    score -= 8.0 * perfect * (1.0 + progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (item_size as f64 / cap).powi(2);
        score += 20.0 * (1.0 - scarcity) * (1.0 - 0.5 * poor_fit) + 5.0 * (1.0 - progress);
    }

    // Lookahead: penalize if the next item cannot fit into post_residual (dead space risk),
    // reward if it fits snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += 4.0 * (1.0 - post / nxt.max(1.0)) * (1.0 + progress);
        } else {
            let snug = 1.0 - ((post - nxt) / cap);
            score -= 3.0 * snug * snug;
        }
    }

    // Mild preference for bins with residuals below the mean (consolidate small leftovers).
    if bin_residual < bin_capacity {
        let dev = (mean_residual - post) / cap;
        if dev > 0.0 {
            score -= 2.0 * dev.min(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries: post_residual in {0..4}, {5..14}, {15..24}, {25..49}, {50..99}, {>=100}
    // Small post_residual (<=10) is "harmonically closed" -> strong reward.
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 24 {
        score -= 20.0;
    } else if post_residual <= 49 {
        // mid class: neutral-ish, slight penalty for awkward dead zone
        score += 5.0;
    } else if post_residual < bin_capacity {
        // large residual in same bin: big leftover is fine (roomy bin)
        score -= 8.0;
    } else {
        // brand-new empty bin candidate
        score -= 15.0;
    }

    // Modulo coupling: does next_item_size fit into post_residual exactly (perfect pairing)?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect harmonic match: reserve this bin for the next item
            score -= 70.0;
        } else if next_item_size < post_residual {
            let leftover2 = post_residual - next_item_size;
            // reward if next item leaves another near-closed residual
            if leftover2 <= 10 {
                score -= 35.0;
            } else {
                score += leftover2 as f64 * 0.15;
            }
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor modulated by mean residual).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Integer-division threshold on item_size: large items should go into emptier bins.
    let item_class = item_size / 20; // 0..4 harmonic class of the item
    score += item_class as f64 * (post_residual as f64 / c) * 10.0;

    // Late in the stream: consolidate more aggressively (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the awkward 1..=20 range are
    // essentially unusable for typical items (>= 1 but likely too small for
    // future arrivals) — penalize them heavily beyond their raw size.
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 3.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0; // near-perfect fit still great
    }

    // Reward bins whose residual matches the lookahead item exactly (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 8.0; // leaves a good slot for next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage spreading across bins.
    score += open_bins_count as f64 * 0.5;

    // A brand-new empty bin should only win when the fit into open bins is bad.
    // Penalize the fresh-bin candidate (bin_residual == bin_capacity) mildly,
    // but relax the penalty as open bins become crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowd = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 55.0 - 45.0 * crowd;
        // If no open bin can fit the item at all, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, close out bins aggressively (tighter packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

