        let used_frac = 1.0 - x;
        if used_frac > 0.8 {
            score -= 4.0;
        }
        if used_frac > 0.95 {
            score -= 3.0;
        }
        if post_residual > 20 && post_residual % 10 != 0 {
            score += (post_residual % 10) as f64 * 0.25;
        }
        if post_residual > 0 && post_residual % 5 == 0 && post_residual <= 30 {
            score -= 2.2;
        }
        if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
            score -= 3.2;
        }
        if post_residual == item_size {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < item_size {
            score -= 2.5;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < next_item_size {
            score += 3.0;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let sliver = post_residual - next_item_size;
            if sliver >= 1 && sliver <= 3 && sliver < item_size {
                score += 2.5;
            }
        }
        let dead_ratio = pr / cap;
        if dead_ratio > 0.3 && used_frac > 0.5 {
            score += 2.0 * dead_ratio * dead_ratio * 10.0;
        }
        if dead_ratio > 0.2 && open_bins_count > 6 {
            score += 1.8 * dead_ratio;
        }
        if dead_ratio > 0.12 && dead_ratio < 0.3 && used_frac > 0.7 {
            score += 1.2 * dead_ratio * (1.0 - progress);
        }
        if dead_ratio > 0.05 && dead_ratio <= 0.12 && next_item_size > 0 && post_residual < next_item_size {
            score += 1.5 * (1.0 - progress);
        }
        if dead_ratio > 0.22 && dead_ratio < 0.28 && used_frac > 0.85 {
            score += 2.5 * dead_ratio;
        }
        if post_residual > 0 {
            let d3 = pr / cap;
            if d3 >= 0.08 && d3 <= 0.22 {
                score += (3.0 + 5.0 * progress) * d3;
            }
        }
        if fitting_bins_count > 4 {
            let tight = 1.0 - (item_size as f64 / pr.max(1.0));
            score += tight * 1.5;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 4.0;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let rem = post_residual - next_item_size;
            if rem >= next_item_size && rem % next_item_size == 0 {
                score -= 2.4;
            }
            if rem > 0 && rem < next_item_size / 3 {
                score += 1.6;
            }
        }
        if used_frac > 0.7 && next_item_size > 0 && pr < mean_residual * 0.6 {
            score -= 1.5;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual + next_item_size) % 10 == 0 {
            score -= 1.8;
        }
        if used_frac > 0.6 && post_residual > 0 && post_residual <= 10
            && next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if mr_ratio > 0.45 && used_frac < 0.6 {
            score += 1.5;
        }
        if post_residual > item_size && (post_residual - item_size) as f64 > mean_residual * 1.5 && open_bins_count > 3 {
            score += 2.0;
        }
        // Waste-after-next penalty (from best heuristic).
        if next_item_size > 0 && post_residual >= next_item_size {
            let waste_after = (post_residual - next_item_size) as f64;
            if waste_after > 0.0 && waste_after < (item_size as f64).min(next_item_size as f64) {
                score += 1.4 * (1.0 - waste_after / 5.0);
            }
        }
    }

    if post_residual == 0 {
        score -= 40.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits snugly (within small slack).
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / 20.0).max(0.0);
    }
    // Next item does NOT fit here: penalize proportionally to how wasted the residual is.
    else if next_item_size > 0 {
        score += 15.0;
    }

    // Last chance: this is the only open bin that fits the item.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer bins whose residual is already below average (tighter bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate: keep it unattractive unless nothing else is viable.
    if is_new_bin {
        score += 35.0 + 5.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper; late in stream, reuse strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but normalize by capacity scale.
    score *= 1.0 + 0.002 * (post_residual as f64 / bin_capacity as f64);

    // Reward near-perfect fits strongly (dead-space avoidance).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize residual windows that are hard to fill later (unusable dead space).
    // Residuals just above typical small-item sizes are awkward.
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 8.0; // tiny sliver: mostly dead space
    } else if r >= 10 && r < 20 {
        score -= 6.0; // still fillable by small items
    } else if r >= 20 && r < 35 {
        score -= 3.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * (item_size as f64);
    }

    // New-bin candidate handling: only attractive when fits are poor or crowded state.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64; // = capacity - item_size for new bin
        // Penalize opening new bins by default...
        score += 55.0;
        // ...but relax penalty late in stream or when open bins are congested.
        score -= 35.0 * progress;
        if open_bins_count > 12 {
            score -= 10.0;
        }
        // If item leaves a big residual in a new bin AND it's a large item, new bin is fine.
        if item_size >= 60 {
            score -= 15.0;
        }
        // If mean residual across open bins is small, fits are tight everywhere -> new bin OK.
        if mean_residual < 15.0 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
        // Avoid new bin when the item would leave a very awkward residual in it.
        if poor_fit > 0 && poor_fit < 12.0 {
            score += 12.0;
        }
        let _ = poor_fit;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0;
        } else if next_item_size <= r && r - next_item_size <= 10 {
            score -= 20.0;
        } else if next_item_size > r {
            // Next item won't fit here anyway; slightly prefer consuming this bin now.
            score += 3.0;
        }
    }

    // Mild preference for filling fuller bins (consistency with Best-Fit core).
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fullness;

    // Congestion control: many open bins -> prefer consolidating into existing ones.
    if open_bins_count > 8 && !is_new_bin {
        score -= 4.0;
    }

    // Small time-horizon modulation: early stream, be conservative about slivers.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && r > 0 && r < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping by stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * (1.0 - norm_pr) * (1.0 - norm_pr));

    // Polynomial coupling: residual squared term scaled by progress.
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: subtract when post residual is small relative to item.
    score -= 12.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: penalize if next item cannot use the leftover space.
    if next_item_size > 0 {
        let waste = (pr - norm_next * cap).max(0.0) / cap;
        score += 6.0 * waste * waste * (0.3 + progress);
        // Reward if next item fits exactly into the post residual.
        if (pr as u32) >= next_item_size {
            score -= 3.0 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual.
    let density = mean_residual / cap;
    score += 2.0 * density * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: discourage opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) - 8.0 * density;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // New-bin candidate: strongly penalize unless current open bins are tight or item is huge.
    if bin_residual == bin_capacity {
        let tight = mean_residual < 12.0 || open_bins_count == 0;
        let big = (item_size as f64) > 0.8 * cap;
        if !(tight || big) {
            score += 60.0 + 0.3 * open_bins_count as f64;
        } else {
            score -= 8.0;
        }
        return score;
    }

    // Harmonic class of post_residual: perfect residue classes are reusable.
    let pr = post_residual;
    let prf = pr as f64;

    // Reward post_residuals that are harmonic with common item sizes (multiples of 10, 25, 50).
    let harmonic = |x: u32| -> f64 {
        let xf = x as f64;
        let mut h = 0.0;
        if x % 10 == 0 { h += 6.0; }
        if x % 25 == 0 { h += 4.0; }
        if x % 50 == 0 { h += 4.0; }
        if xf < 10.0 && xf > 0.0 { h -= 8.0; } // dead space penalty
        h
    };
    score -= harmonic(pr);

    // Modulo-16 class of post_residual: mid-band residues are awkward.
    let m = pr % 16;
    if m >= 1 && m <= 5 { score += 4.0; }
    if m >= 11 && m <= 15 { score += 2.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            if (pr - next_item_size) % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this residual: penalize small residuals
            score += 3.0 * (10.0_f64.min(prf) / 10.0);
        }
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score += 0.15 * (prf - mean_residual);

    // Late in the stream, be greedier: minimize waste more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * prf;

    // Exact fit is always best.
    if pr == 0 { score -= 40.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below the smallest item, ~10)
    // are almost worthless; penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // "Awkward zone": only tiny items can use it.
        score += (20 - post_residual) as f64 * 1.5;
    } else {
        // Larger usable residuals are mildly rewarded (already captured by base).
        score -= 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residuals that exactly accommodate the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize residuals that nearly fit the next item (tempting but dead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage spreading across bins / opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large relative to
    // typical residuals or no good fit exists. Penalize mildly by default,
    // but discount the penalty when mean residual is small.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            // No open bin really fits well: opening a new bin is reasonable.
            score -= 30.0;
        } else {
            score += 25.0 + mean_gap * 0.5;
        }
    }

    // Early stream: slightly prefer tight packing; late stream: keep bins open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward filling the bin nearly completely (dead-space avoidance).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item could use the post_residual,
    // reward leaving exactly that much space; penalize wasted space the
    // next item cannot use.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            score -= 15.0 * (nx / 100.0);
        } else {
            // dead space for the next item: penalize proportionally
            score += 8.0 * (1.0 - (post_residual as f64) / nx.max(1.0));
        }
    }

    // Global state: penalize opening a new bin when many open bins already
    // have slack; new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 45.0;
        // Late in the stream, avoid proliferating bins even more strongly.
        new_bin_penalty += 30.0 * progress;
        // More open bins with mean slack -> stronger penalty for new bin.
        new_bin_penalty += 5.0 * (open_bins_count as f64).sqrt();
        new_bin_penalty += mean_residual * 0.3;
        // If next item is large and this item is small, opening a fresh bin
        // may be reasonable: soften penalty.
        if next_item_size >= 60 && item_size <= 30 {
            new_bin_penalty -= 25.0;
        }
        // If no open bin fits at all (this is the only option), the penalty
        // is moot; make it clearly negative so a new bin is opened.
        if fitting_bins_count == 0 {
            new_bin_penalty = -100.0;
        }
        score += new_bin_penalty;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor)
        // but modulate by global mean residual: favor bins below mean slack
        // (they are the "tight" ones) to keep loose bins available.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
        // Slight preference for bins that can also hold the next item later.
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 4.0;
        }
    }

    // Time horizon: early on, be more exploratory (accept looser fits to
    // learn the distribution); late, be greedy about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (1.0 - tightness);
    score += 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = (pr / cap).clamp(0.0, 1.0);
    let t = progress.clamp(0.0, 1.0);
    // Smooth interaction: tight fits rewarded more as stream progresses.
    let tight = (1.0 - x) * (1.0 - x);
    score -= 12.0 * tight * (0.4 + 0.6 * t);

    // Penalize near-full residual only mildly early, strongly late (dead space matters late).
    let small = x * x * (3.0 - 2.0 * x); // smoothstep on residual fraction
    score += 6.0 * small * (1.0 - t);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * t;
    }

    // New-bin candidate: penalize opening new bins unless residual would be very small
    // relative to mean residual of open bins (i.e., current bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = ((mean_residual / cap) - 0.5).abs();
        score += 20.0 - 14.0 * fragmentation - 6.0 * t;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly (smooth).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_q = 1.0 - ((pr - next_item_size as f64) / cap).clamp(0.0, 1.0);
        score -= 10.0 * fit_q * fit_q;
    } else if next_item_size > 0 {
        // Next item cannot fit here; slight penalty scaled by how much it misses.
        let miss = ((next_item_size as f64 - pr) / cap).clamp(0.0, 1.0);
        score += 4.0 * miss * (1.0 - t);
    }

    // Mild penalty for many open bins (encourage consolidation), smoothed.
    score += 0.15 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" small classes (0 or >= next item) are preferred.
    let cap = bin_capacity as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Classify post_residual by integer division into harmonic bands of capacity/5.
    let band = post_residual / (bin_capacity / 5).max(1);
    let band_penalty = match band {
        0 => -50.0,                       // tiny leftover, near-perfect packing
        1 => 10.0,                        // awkward dead space (20-40)
        2 => -5.0,                        // medium usable
        3 => 5.0,
        _ => 0.0,
    };
    score += band_penalty;

    // Reward if the leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 {
        // leftover useless for the next item: penalize proportionally to waste
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity; make the
    // empty bin attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.75;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced: no alternative
        } else if fitting_bins_count == 1 {
            // an existing last-chance bin exists; keep new bin less attractive
            score += 60.0;
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Modulo-class harmonics on post_residual: leftovers that are multiples
    // of common item sizes (10,20,25) are reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
    }

    // Prefer tighter bins when many bins are open (consolidation pressure).
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Small penalty scaled by item size fraction to prefer placing large
    // items into fuller bins.
    score += (item_size as f64 / cap) * (bin_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead space: residuals too small for the minimum item size are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }

    // Penalize residuals that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0;
    }

    // Reward residuals that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (compact filling).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when the item barely fits
    // nowhere well; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 10.0;
        if fitting_bins_count <= 1 {
            score -= 250.0; // allow new bin when no good alternative exists
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_capacity - bin_residual) as f64 * (-0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but avoid tiny useless slivers.
    if post_residual < 10 {
        // Perfectly compacted bin: strong reward.
        score -= 40.0;
    } else if post_residual > 60 {
        // Large dead space created; penalize proportionally.
        score += (post_residual as f64 - 60.0) * 0.8;
    }

    // 2-step lookahead: reward bins whose post_residual closely matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if pr >= nxt {
            // Next item can chain into this bin: reward exact match.
            score -= 30.0 * (1.0 - diff / 100.0);
            if diff < 5.0 {
                score -= 25.0; // near-perfect chain
            }
        } else {
            // Next item cannot fit here; penalize if we wasted space that
            // would have accommodated it (gap is small).
            let gap = nxt - pr;
            if gap < 15.0 {
                score += (15.0 - gap) * 1.2; // near-miss: bad sign
            }
        }
        // Coupling with mean residual: if this bin's post_residual deviates
        // strongly below the fleet mean, it's an outlier worth exploiting.
        let dev = pr - mean_residual;
        score += dev * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no existing bin can fit, the new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // Late in the stream, opening bins is cheaper than fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Mild preference for tighter source bins when many are open.
    score += (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect and perfect fits (minimize dead space).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    }

    // Lookahead (k=2): strongly reward placements that let the next item
    // finish off this bin almost exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else if gap <= 5 {
                score -= 15.0;
            } else if gap <= 12 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here: leftover is likely dead space.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, avoid
    // opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins: residual below the current mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else if (bin_residual as f64) > mean_residual * 1.5 {
        score += 2.0;
    }

    // Mild fragmentation pressure: with many open bins, favor compacting
    // into existing ones rather than spreading.
    score += open_bins_count as f64 * 0.08;

    // Time horizon: late in the stream, prioritize closing out open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.75 {
        score -= 3.0;
    } else if progress > 0.4 {
        score -= 1.0;
    }

    // New-bin candidate penalty: opening a fresh bin should only win when
    // every existing fit leaves large unusable leftovers. Scale penalty
    // with item size (large items into a fresh bin leave less usable room).
    if bin_residual == bin_capacity {
        score += 12.0 + item_size as f64 * 0.15;
        // But if the lookahead item is large and would pair well in a fresh
        // bin, soften the penalty slightly.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let slack = bin_capacity - next_item_size - item_size;
            if slack <= 10 {
                score -= 8.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // so mid-sized dead space is punished disproportionately more than tiny scraps.
    let mut score = pr + (pr * pr) / (2.0 * cap);

    // Smooth non-linear coupling with stream progress: late in the stream,
    // dead space matters more (fewer future items to fill it).
    score *= 1.0 + 0.5 * progress * (pr / cap);

    // Reward tight fits: small post-residual relative to item size.
    let tightness = 1.0 - pr / cap;
    score -= (item_size as f64) * tightness * tightness * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if the next item would fit the post-residual,
    // reward this placement (chaining placements).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 4.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // Post-residual too small for next item: mild penalty proportional to waste.
        score += 0.05 * pr * progress;
    }

    // New-bin candidate (empty bin): penalize so it's only chosen when all
    // open bins fit poorly; the penalty relaxes slightly early in the stream.
    if bin_residual == bin_capacity {
        score += 40.0 - 10.0 * progress;
        // If the next item is large and this bin would be nearly emptied by it,
        // opening a fresh bin becomes more attractive.
        if next_item_size > 0 && (next_item_size as f64) >= 0.5 * cap {
            score -= 12.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (smaller than average) — non-linear attraction.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // Mild pressure to consolidate among many open bins.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by integer division
    // into capacity-fraction buckets. Small leftovers (<10) are unusable dead space
    // since items are >= 1; penalize heavily to prefer bins whose remainder
    // stays "usable" for future items.
    let cls = post_residual / 10; // harmonic class 0..=10
    match cls {
        0 => {
            // Dead space too small for most items: penalize unless it's a perfect fit
            score += 40.0;
        }
        1 => {
            // Residual 10..19: only fits small items; mildly penalize
            score += 12.0;
        }
        2 => {
            // Residual 20..29: fits mid items; slightly reward
            score -= 4.0;
        }
        3 => {
            // Residual 30..39: sweet spot for typical items
            score -= 10.0;
        }
        4 => {
            // Residual 40..49: still good
            score -= 8.0;
        }
        _ => {
            // Large residual: fine, but wasteful use of a big bin for a small item
            score -= 2.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but not perfectly: small bonus scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - tight / 50.0).max(0.0);
        } else {
            // Next item cannot fit here: mild penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / 50.0).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 80.0;
        // Late in stream, opening bins is less costly (fewer future items to waste)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * progress;
        // If many open bins with slack, opening yet another is bad
        score += 3.0 * open_bins_count as f64;
    }

    // Prefer filling bins below the mean residual (balance avoidance of fragmentation)
    score += 0.15 * ((post_residual as f64) - mean_residual).max(0.0);

    // Tight-fit bonus: reward placements leaving residual in harmonic sweet zone
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * (frac * std::f64::consts::PI).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any gap too small for the minimum item
    // (1 here, but small gaps < ~15 are statistically hard to reuse) is dead space.
    if post_residual < 10 {
        // Perfect fill: huge reward.
        score -= 500.0;
    } else if post_residual < 20 {
        score += 60.0; // risky tiny gap
    } else if post_residual < 35 {
        score += 25.0; // moderately awkward gap
    }

    // Reward tight fits: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 150.0;
        } else if post_residual < next_item_size {
            score += 20.0; // leftover unusable for the immediate next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless current bins
    // would create bad dead space. Penalize proportionally to how well open
    // bins could still be used.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 140.0 + 8.0 * open_bins_count as f64;
        // If the item leaves a large gap in an open bin anyway, new bin is OK.
        if post_residual > 45 && bin_residual == bin_capacity {
            new_bin_score -= 100.0;
        }
        score += new_bin_score;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones (larger residuals get relatively worse).
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins whose residual deviates from the mean
    // toward being smaller (converge residuals).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize leaving a dead gap that no plausible item can use.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Dead-space penalty: small post_residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if gap < nxt {
            // Gap unusable by next item: penalize proportionally to how close we came
            // (near-miss wastes more capacity than a tiny gap).
            let miss = (nxt - gap) / 100.0;
            score += 25.0 * miss;
        } else {
            // Reward when the next item fits snugly in the remaining space.
            let snug = 1.0 - ((gap - nxt) / 100.0);
            score -= 20.0 * snug;
        }
    }

    // 2-step lookahead coupling: reward chains where post_residual ~ next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = 1.0 - (post_residual as f64 - next_item_size as f64) / 100.0;
        score -= 15.0 * chain;
    }

    // Relative residual alignment: bins whose residual is close to the item deserve priority.
    let dev = (bin_residual as f64 - item_size as f64).abs();
    score += 0.10 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make an empty bin attractive only when the item fits it
    // perfectly or open bins are badly fragmented (mean residual large & scattered).
    if bin_residual == bin_capacity {
        let perfect = (bin_capacity as f64 - item_size as f64).abs() < 1.0;
        if perfect {
            score -= 45.0;
        } else {
            // Penalize new bins mildly; relax penalty late in the stream or when
            // open-bin residuals are too small to be useful.
            let fragmentation = mean_residual / bin_capacity as f64;
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let penalty = 50.0 - 25.0 * fragmentation - 15.0 * progress;
            score += penalty.max(5.0);
        }
    }

    // Mild preference for consolidating into bins below mean residual (pack dense bins first).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Dead-space penalty: small leftover space that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leftover becomes dead-ish space.
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, prefer filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.3;
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // Penalize bins that are much emptier than the mean (hoarding), mildly.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when item is large and would leave a
    // clean, reusable residual, or when this item fits nothing well elsewhere.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, discounted for large items.
        score += 40.0 - fill * 35.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // new bin can also host next item
        }
        if fitting_bins_count > 2 {
            score += 10.0; // plenty of alternatives exist, keep new bin closed
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits via quadratic coupling of post_residual with progress.
    let mut score = post * (1.0 + 1.5 * progress) - 20.0 * progress * norm_post * (1.0 - norm_post);

    // Penalize dead space that nothing else could use: smooth cubic in post_residual.
    score += 0.002 * post * post * post / (cap * cap);

    // Last-chance bonus: if this is the only fitting bin, reward using it strongly.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if the next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            let gap = nxt - post;
            score += 0.05 * gap;
        }
    }

    // Crowd pressure: many open bins with high mean residual -> favor consolidation.
    let pressure = open_bins_count as f64 * (mean_residual / cap);
    score -= 0.5 * pressure * progress;

    // New-bin candidate: make empty bins slightly unattractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * progress - 0.3 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual bucketed by capacity/4.
    let quarter = bin_capacity / 4;
    let post_class = (post_residual / quarter) as f64; // 0..=4

    // Reward near-perfect fits (class 0 => post_residual < 25, dead space small).
    score -= post_class * post_class * 2.0;

    // Exact / tiny-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= quarter / 2 {
        score -= 25.0;
    }

    // Penalize residuals that no future item (min size 1, typical 10..80) can use.
    // A residual < 10 is dead space unless it is 0.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic compatibility: does the lookahead item fit into post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this bin will be exactly filled by the next item.
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // Next item fits: value the remaining slack by how reusable it stays.
            let after2 = post_residual - next_item_size;
            if after2 < 10 && after2 > 0 {
                score += 15.0; // creates fresh dead space
            } else {
                score -= 20.0; // keeps bin alive
            }
        } else {
            // Next item cannot use this bin: mild penalty scaled by mismatch class.
            score += ((next_item_size - post_residual) / quarter) as f64 * 8.0;
        }
    }

    // Last-chance logic: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0; // strongly prefer using it over opening a new bin
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 50.0;
        // Cheaper to open a new bin early when few bins exist and stream is long.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If many open bins are congested (low mean residual), new bin is fine.
        if mean_residual < 20.0 && open_bins_count > 3 {
            score -= 20.0;
        }
        // If the item fits poorly everywhere (large post_residual relative), new bin attractive.
        if post_residual > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Prefer denser bins: reward placing into bins with less residual.
        score += (bin_residual as f64 - post_residual as f64) * 0.0; // neutral filler
        // Slight preference for bins already below mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Many open bins: encourage closing them out by filling small-residual ones.
        if open_bins_count > 6 && post_residual < quarter {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space = gap too small for the smallest plausible item (1..100 stream).
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 25 {
            score += 25.0; // near-dead gap
        } else if post_residual < 50 {
            score += 8.0; // moderately wasteful
        } else {
            score -= 10.0; // large residual still useful
        }
    } else {
        score -= 40.0; // perfect fill, strongly reward
    }

    // Reward when this bin's post-residual can host the lookahead item exactly well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 12.0; // lookahead won't fit here -> residual likely dead
        }
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when the item is huge relative
    // to all residuals and opening fresh avoids dead space; otherwise penalize.
    if bin_residual == bin_capacity {
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 20.0; // big item, poor fits elsewhere -> open fresh
        } else {
            score += 45.0; // prefer existing bins generally
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little slack left afterwards.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack_after_next as f64 / post_residual.max(1) as f64);
    }
    // Next item cannot use this bin's remainder: penalize proportionally to wasted space.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 0.35 * (post_residual as f64) * (next_item_size as f64 / 100.0);
    }

    // Compare post_residual against mean residual: keep bins balanced, avoid stragglers.
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Last chance: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins would leave large dead space
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && next_item_size <= item_size {
            1.0
        } else {
            0.0
        };
        score = item_size as f64 * 0.9 + 10.0 * poor_fit;
        if fitting_bins_count == 1 {
            score += 50.0; // don't open a new bin when an existing bin is the only option
        }
    }

    // Late in the stream, tighten packing to avoid many half-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.15;

    // Slight penalty for tiny unusable remainders (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}
